/** Federal part of the combined rate, by country. Anything not listed is all regional. */
const FEDERAL_RATES: Record<string, number> = { CA: 0.05 };

/**
 * The federal and regional parts (fractions) of the rate for `taxClass` goods
 * shipped to `address`. They add up to `taxRateFor`.
 */
export function taxComponentsFor(
  address: Address,
  taxClass: TaxClass,
  fallback: number,
): { federal: number; regional: number } {
  if (taxClass === 'exempt') return { federal: 0, regional: 0 };
  const country = address.country.toUpperCase();
  const region = address.region.toUpperCase();
  const known = RATES[country]?.[region];
  const full = known ?? fallback;
  const federal = known === undefined ? 0 : Math.min(FEDERAL_RATES[country] ?? 0, full);
  const share = taxClass === 'reduced' ? REDUCED_SHARE : 1;
  const round = (n: number) => Math.round(n * 1e6) / 1e6;
  return { federal: round(federal * share), regional: round((full - federal) * share) };
}
